attribute vec3 aO, aE; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK, vLen;
    void main(){ float u = uTime - aT; if (u < 0. || u > (aK < .5 || aK > 1.5 ? 4.500 : 0.700)){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){ float S = 3.800; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      if (aK > 1.5){ vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.35 + .05*sin(uTime*1.3), 0.), 1.);   /* the orb, floating above the centre */
        float S = 1.05*(1. - pow(1. - clamp(u/.3, 0., 1.), 3.))*(1. - smoothstep(4.000, 4.500, u));
        mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv; return; }
