uniform float uTime; uniform vec3 uV, uL, uD; varying vec2 vP; varying float vU, vK, vLen; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    void main(){ vec3 c = vec3(0.); float al = 0.;
      if (vK < .5){
        float r = length(vP), a = atan(vP.y, vP.x), R = 3.500;
        float fin = eox(clamp((vU - .3)/1.6, 0., 1.)), fout = 1. - smoothstep(4.000, 4.500, vU);
        float Rr = R*mix(.4, 1., fin), f = fin*fout;
        float rim = line(r - Rr, .03)*.22 + exp(-pow((r - Rr)/.25, 2.))*.04;              /* faint outer border */
        float sw = a + 2.2*log(max(r, .05)) - vU*.35;                                     /* 4 wide spiral arms turning inward, slowly */
        float arm = pow(.5 + .5*cos(4.*sw), 5.)*smoothstep(Rr, Rr*.6, r)*smoothstep(.55, 1.1, r);
        float streak = .6 + .4*sin(sw*4. + r*6. - vU*3.);
        float hz = line(r - .62, .06)*1.2;                                                 /* violet event horizon */
        float core = smoothstep(.62, .45, r);                                              /* the black centre stays visible */
        c = (uV*rim + uL*line(r - Rr, .01)*.08)*f;                                        /* only the faint outer border stays on the ground */
        al = 0.;
