        vec2 e = vec2(q.x, q.y*3.2); float er = length(e), ea = atan(e.y, e.x);
        float disk = line(er - .62, .035)*(.55 + .35*sin(ea*3. - uTime*2.5))*(1. - core*step(0., q.y));   /* ring passes behind the top */
        float swirl = pow(.5 + .5*cos(a*2. + r*9. - uTime*3.), 4.)*smoothstep(.95, .4, r)*smoothstep(.34, .5, r)*.35;
        c = uV*(rimL + disk*.62 + swirl*.35 + exp(-r*r*8.)*.018) + uL*(line(r - .365, .005)*.35 + disk*.12);
